#include <bits/stdc++.h>
#define push_back pb
#define first x
#define second y

using namespace std;
typedef long long LL;
typedef pair<int,int> PII;
typedef vector<int> VI;

const int MAXN=6555;
struct Edge {
    int to, cap, cost, rev;
    Edge() {}
    Edge(int t, int c, int co, int r): to(t), cap(c), cost(co), rev(r) {}
};

const int INF=0x3f3f3f3f;

struct MinCostMaxFlow {
    int V, H[MAXN], dist[MAXN], preV[MAXN], preE[MAXN];
    vector<Edge> G[MAXN];
    void initialize(int n) {
        V=n;
        for(int i=0; i<=V; ++i) G[i].clear();
    }
    void addEdge(int from, int to, int cap, int cost) {
        G[from].push_back(Edge(to, cap, cost, (int)G[to].size()));
        G[to].push_back(Edge(from, 0, -cost, (int)G[from].size() - 1));
    }
    int computeMinCost(int s, int t, int flow) {
        int totalFlow=0, totalCost=0;
        fill(H, H+V+1, 0);
        while(flow > 0) {
            priority_queue<PII, vector<PII>, greater<PII>> pq;
            fill(dist, dist+V+1, INF);
            dist[s]=0; pq.push({0,s});
            while(!pq.empty()) {
                PII current=pq.top(); pq.pop();
                int v=current.second;
                if(dist[v]<current.first) continue;
                for(int i=0; i<(int)G[v].size(); ++i) {
                    Edge &e=G[v][i];
                    if(e.cap>0 && dist[e.to]>dist[v]+e.cost+H[v]-H[e.to]) {
                        dist[e.to]=dist[v]+e.cost+H[v]-H[e.to];
                        preV[e.to]=v;
                        preE[e.to]=i;
                        pq.push({dist[e.to], e.to});
                    }
                }
            }
            if(dist[t]==INF) break;
            for(int i=0; i<=V; ++i) H[i]+=dist[i];
            int d=flow;
            for(int v=t; v!=s; v=preV[v]) d=min(d, G[preV[v]][preE[v]].cap);
            flow-=d; totalFlow+=d; totalCost+=d*H[t];
            for(int v=t; v!=s; v=preV[v]) {
                Edge &e=G[preV[v]][preE[v]];
                e.cap-=d;
                G[v][e.rev].cap+=d;
            }
        }
        return totalCost;
    }
} minCostFlow;

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.in","r",stdin);
    freopen("out.out","w",stdout);
#endif
    int n,m,k,c,d;
    cin>>n>>m>>k>>c>>d;
    minCostFlow.initialize(n*(n+55)+2);
    for(int i=0; i<k; i++){
        int u; cin>>u;
        minCostFlow.addEdge(0, u, 1, 0);
    }
    vector<PII> edges(m);
    for(int i=0; i<m; i++) cin>>edges[i].x>>edges[i].y;
    int target=n*(n+55)+1;
    for(int t=0; t<n+54; t++){
        for(PII e: edges){
            for(int j=1; j<=k; j++){
                minCostFlow.addEdge(e.x+t*n, e.y+(t+1)*n, 1, c+d*(j*2-1));
                minCostFlow.addEdge(e.y+t*n, e.x+(t+1)*n, 1, c+d*(j*2-1));
            }
        }
        for(int i=2; i<=n; i++){
            minCostFlow.addEdge(i+t*n, i+(t+1)*n, k, c);
        }
        minCostFlow.addEdge(1+t*n, target, k, 0);
    }
    cout<<minCostFlow.computeMinCost(0, target, k)<<endl;
    return 0;
}
